import{t as e}from"./types-DccqHlFD.js";var t=`A worm gear speed reducer is a mechanical device that reduces the rotational speed of a motor while increasing the output torque (turning force).`,n=[`Worm: A screw-like shaft that rotates when driven by a motor.`,`Worm wheel: A gear that meshes with the worm and rotates at a lower speed.`],r=[`/gearbox/support/20200919_115957.jpg`,`/gearbox/support/20201113_131021.jpg`,`/gearbox/support/20201113_131048.jpg`,`/gearbox/support/20210301_153953.jpg`,`/gearbox/support/20210301_153956.jpg`,`/gearbox/support/20210301_155056.jpg`,`/gearbox/support/20210301_155101.jpg`,`/gearbox/support/473018886_597355326335626_1086014694302454111_n.jpg`,`/gearbox/support/473281980_597355483002277_498770356072703946_n.jpg`];function i(i,a){return e({name:i,category:`Gear Reducers`,subtitle:`Worm Gear Reducer`,description:t,features:n,specs:{Type:`Worm Gear Reducer`,Series:i},imagePath:a,galleryImages:r.slice(2,6)})}var a=[i(`WPA`,`/products/gearbox/wpa.webp`),i(`WPO`,`/products/gearbox/wpo.webp`),i(`WPX`,`/products/gearbox/wpx.webp`)],o={path:`/gearbox`,title:`Worm Gear Reducer`,description:t,productGroups:[{products:a,photos:r}],sections:[{kind:`list`,eyebrow:`What is a worm gear speed reducer?`,intro:`It consists mainly of two parts:`,items:n,paragraphs:[`These components work together to transfer power between shafts, usually arranged at 90 degrees to each other.`]},{kind:`list`,eyebrow:`The working process`,intro:`The working process is simple:`,items:[`The motor rotates the worm shaft at high speed.`,`The worm drives the worm wheel through contact between their teeth.`,`The worm wheel rotates more slowly than the worm.`,`The output shaft delivers lower-speed rotation with higher torque.`]},{kind:`groups`,eyebrow:`Applications of Worm Gear Speed Reducers`,intro:[`A worm gear speed reducer is used in industrial machines to reduce motor speed, increase output torque, and transfer power between shafts, usually at a 90° angle.`],subheading:`Common industrial applications`,groups:[{title:`Conveyor systems`,items:[`Controls the speed of conveyor belts.`,`Provides sufficient torque to move products.`,`Used in factories, warehouses and production lines.`]},{title:`Lifting and hoisting equipment`,items:[`Reduces motor speed for controlled lifting.`,`Provides high output torque.`,`Used in winches and some hoisting mechanisms.`,`Safety note: A suitable brake or load-holding system may be necessary.`]},{title:`Packaging machines`,items:[`Controls the movement of packaging materials.`,`Drives filling, sealing and wrapping mechanisms.`,`Helps maintain consistent operating speed.`]},{title:`Mixing machines`,items:[`Reduces the speed of mixer blades.`,`Provides torque for mixing liquids, powders and other materials.`,`Used in food processing and chemical production, with appropriate equipment materials and sealing.`]},{title:`Valves and gate actuators`,items:[`Provides controlled rotary movement.`,`Helps open and close valves or gates.`,`Used in water treatment plants and industrial piping systems.`]},{title:`Rotary tables and positioning equipment`,items:[`Reduces rotational speed.`,`Provides controlled movement for positioning workpieces.`,`Used in machine tools, assembly equipment and indexing tables.`]},{title:`Automatic gates and doors`,items:[`Reduces motor speed for smoother movement.`,`Provides the torque needed to move heavy gates.`,`Used in industrial doors and gate operating systems.`]}]}]};export{a as n,o as t};